     1	package hotel.messages;
     2	
     3	import java.sql.Connection;
     4	import java.sql.PreparedStatement;
     5	import java.sql.ResultSet;
     6	import java.sql.SQLException;
     7	import java.util.ArrayList;
     8	import java.util.List;
     9	import javax.sql.DataSource;
    10	
    11	/** Every message the inn sent, so the front desk can check what each guest received. */
    12	public final class SentMessages {
    13	
    14	    private final DataSource dataSource;
    15	
    16	    public SentMessages(DataSource dataSource) {
    17	        this.dataSource = dataSource;
    18	    }
    19	
    20	    Message add(OutgoingMessage outgoing) {
    21	        Message main = saveMessage(outgoing);
    22	        for (OutgoingMessage additional : outgoing.additionalMessages()) {
    23	            saveMessage(additional);
    24	        }
    25	        return main;
    26	    }
    27	
    28	    private Message saveMessage(OutgoingMessage outgoing) {
    29	        try (Connection connection = dataSource.getConnection();
    30	                PreparedStatement insert = connection.prepareStatement(
    31	                        "INSERT INTO messages (channel, recipient, subject, body, status) VALUES (?, ?, ?, ?, ?) RETURNING id")) {
    32	            insert.setString(1, outgoing.channel());
    33	            insert.setString(2, outgoing.to());
    34	            insert.setString(3, outgoing.subject());
    35	            insert.setString(4, outgoing.body());
    36	            insert.setString(5, outgoing.status().name());
    37	            try (ResultSet generated = insert.executeQuery()) {
    38	                generated.next();
    39	                return new Message(
    40	                        generated.getLong("id"),
    41	                        outgoing.channel(),
    42	                        outgoing.to(),
    43	                        outgoing.subject(),
    44	                        outgoing.body(),
    45	                        outgoing.status());
    46	            }
    47	        } catch (SQLException failure) {
    48	            throw new IllegalStateException("could not keep the message to " + outgoing.to(), failure);
    49	        }
    50	    }
    51	
    52	    public List<Message> all() {
    53	        try (Connection connection = dataSource.getConnection();
    54	                PreparedStatement select = connection.prepareStatement(
    55	                        "SELECT id, channel, recipient, subject, body, status FROM messages ORDER BY id");
    56	                ResultSet rows = select.executeQuery()) {
    57	            List<Message> messages = new ArrayList<>();
    58	            while (rows.next()) {
    59	                messages.add(new Message(
    60	                        rows.getLong("id"),
    61	                        rows.getString("channel"),
    62	                        rows.getString("recipient"),
    63	                        rows.getString("subject"),
    64	                        rows.getString("body"),
    65	                        MessageStatus.valueOf(rows.getString("status"))));
    66	            }
    67	            return messages;
    68	        } catch (SQLException failure) {
    69	            throw new IllegalStateException("could not read the sent messages", failure);
    70	        }
    71	    }
    72	}
